/**
 * How Ardent Core and Ardent Field reach the engine. Both apps hold one
 * Connection and never care which kind it is:
 *
 * - live: a running engine over HTTP (npm start in engine/).
 * - demo: the same engine running inside the app, on the Manchester demo
 *   firm, for the published prototypes. Changes are kept in the browser or
 *   phone so a demo survives a reload. Nothing in demo mode is secret: it is
 *   one person's copy of made-up records.
 *
 * The session token is kept in the app's storage, so a reload stays signed in.
 */
import type { ArdentClient } from '../data/core/client'
import type { Photo } from '../data/core/model'
import { createEngine, EngineError } from './engine'
import { adminCall, callEngine, createHttpClient, photoLink, type SignedIn, signIn as httpSignIn, signOut as httpSignOut, uploadPhoto } from './http-client'
import type { Platform } from './platform'
import { DEMO_PASSWORD, demoData, demoUsers, shiftDemo } from './seed'
import type { Data, Role, Store } from './store'

/** Where an app keeps small things between launches: localStorage on the web, AsyncStorage on a phone. */
export interface KeyValue {
  get(key: string): string | null | Promise<string | null>
  set(key: string, value: string): void | Promise<void>
  remove(key: string): void | Promise<void>
}

export type Organisation = SignedIn['organisations'][number]

export interface Me {
  user: SignedIn['user']
  organisation: Organisation
  role: Role
}

export interface Connection {
  mode: 'live' | 'demo'
  /** Signed in already from an earlier visit? */
  restore(): Promise<Me | undefined>
  signIn(email: string, password: string): Promise<Me>
  signOut(): Promise<void>
  /** The records, as the signed-in person. Throws unauthenticated when signed out. */
  client: ArdentClient
  /** Firm admin calls (members, invites, crew). */
  admin<T = unknown>(name: string, ...args: unknown[]): Promise<T>
  /**
   * One call by name, with a request id the caller keeps, so an offline queue
   * can replay it safely: the engine applies each request id once.
   */
  call(method: string, args: unknown[], requestId?: string): Promise<unknown>
  /** Send a photo's image once there is signal. Demo mode keeps the image on the device. */
  uploadPhoto(photoId: string, body: Blob | ArrayBuffer | Uint8Array, contentType: string): Promise<{ uri: string } | undefined>
  /** Something an <img> or <Image> can show for a photo record. */
  photoUrl(photo: Photo): Promise<string>
  /** For demo mode: put the demo firm back as it started. */
  reset?(): Promise<void>
}

const TOKEN = 'ardent.session'
const ORG = 'ardent.org'

function pick(organisations: Organisation[], wanted: string | null) {
  const org = organisations.find((o) => o.id === wanted) ?? organisations[0]
  if (!org) throw new EngineError('forbidden', "you aren't in a firm on Ardent yet")
  return org
}

/** Calls made before sign-in (or after sign-out) fail the same way in both modes. */
function guarded(get: () => ArdentClient | undefined): ArdentClient {
  return new Proxy({} as ArdentClient, {
    get: (_, area: string) =>
      new Proxy(
        {},
        {
          get: (_, name: string) =>
            (...args: unknown[]) => {
              const client = get()
              if (!client) return Promise.reject(new EngineError('unauthenticated', 'sign in first'))
              return (client as never as Record<string, Record<string, (...a: unknown[]) => unknown>>)[area][name](...args)
            },
        },
      ),
  })
}

/** A running engine over HTTP. */
export function connectLive(baseUrl: string, storage: KeyValue, doFetch?: typeof fetch): Connection {
  let token: string | undefined
  let orgId: string | undefined
  const conn = { baseUrl, token: () => token, get orgId() { return orgId }, fetch: doFetch }
  const http = createHttpClient(conn)

  const settle = async (organisations: Organisation[], user: SignedIn['user']): Promise<Me> => {
    const organisation = pick(organisations, await storage.get(ORG))
    orgId = organisation.id
    await storage.set(ORG, orgId)
    return { user, organisation, role: organisation.role }
  }

  return {
    mode: 'live',
    async restore() {
      token = (await storage.get(TOKEN)) ?? undefined
      if (!token) return undefined
      const res = await (doFetch ?? fetch)(`${baseUrl}/api/me`, { headers: { authorization: `Bearer ${token}` } }).catch(() => undefined)
      if (!res?.ok) {
        if (res?.status === 401) {
          token = undefined
          await storage.remove(TOKEN)
        }
        return undefined
      }
      const me = (await res.json()) as { user: SignedIn['user']; organisations: Organisation[] }
      return settle(me.organisations, me.user)
    },
    async signIn(email, password) {
      const s = await httpSignIn(baseUrl, email, password, doFetch)
      token = s.token
      await storage.set(TOKEN, s.token)
      return settle(s.organisations, s.user)
    },
    async signOut() {
      if (token) await httpSignOut(conn).catch(() => undefined)
      token = undefined
      await storage.remove(TOKEN)
    },
    client: guarded(() => (token ? http : undefined)),
    admin: (name, ...args) => adminCall(conn, name, ...args),
    call: (method, args, requestId) => callEngine(conn, method, args, requestId),
    uploadPhoto: (photoId, body, contentType) => uploadPhoto(conn, photoId, body, contentType),
    photoUrl: async (photo) => (photo.uri.startsWith('ardent:') ? photoLink(conn, photo.id) : photo.uri),
  }
}

/**
 * A stand-in for the server's crypto, for the in-app demo only. It is not
 * secure and never runs on a server: the demo has no secrets to protect.
 */
const demoPlatform: Platform = {
  hashPassword: (p) => `demo$${p}`,
  verifyPassword: (p, stored) => stored === `demo$${p}`,
  newToken: () => (globalThis.crypto?.randomUUID?.() ?? `${Date.now()}${Math.random()}`).replace(/-/g, ''),
  hashToken: (t) => `t$${t}`,
  sign: (secret, text) => {
    let h = 2166136261
    for (const c of `${secret}:${text}`) h = Math.imul(h ^ c.charCodeAt(0), 16777619) >>> 0
    return h.toString(36)
  },
  same: (a, b) => a === b,
  randomSecret: () => `${Math.random()}`.slice(2),
}

const DEMO_DATA = 'ardent.demo.v1'

/** The demo firm's sign-ins, for a "try it as" picker. */
export const demoPeople = demoUsers.map(({ email, name, role }) => ({ email, name, role, password: DEMO_PASSWORD }))

/** The engine running inside the app on the demo firm. */
export async function connectDemo(storage: KeyValue, opts: { today?: string } = {}): Promise<Connection> {
  // The demo's busy day is today, in UK time.
  const today = opts.today ?? new Date().toLocaleDateString('en-CA', { timeZone: 'Europe/London' })
  const fresh = () => shiftDemo(demoData(demoPlatform), today)
  const saved = await storage.get(DEMO_DATA)
  let data: Data
  try {
    data = saved ? (JSON.parse(saved) as Data) : fresh()
  } catch {
    data = fresh()
  }
  let timer: ReturnType<typeof setTimeout> | undefined
  const store: Store = {
    data,
    commit() {
      clearTimeout(timer)
      timer = setTimeout(() => void storage.set(DEMO_DATA, JSON.stringify(store.data)), 150)
    },
  }
  let engine = createEngine(store, demoPlatform)
  let session: { me: Me; client: ArdentClient; admin: Record<string, (...a: unknown[]) => Promise<unknown>> } | undefined

  const open = async (token: string): Promise<Me | undefined> => {
    const user = engine.userForToken(token)
    if (!user) return undefined
    const organisation = pick(engine.organisationsFor(user.id), await storage.get(ORG))
    const { client, admin } = engine.as({ userId: user.id, orgId: organisation.id })
    const me = { user, organisation, role: organisation.role }
    session = { me, client, admin: admin as never }
    return me
  }

  const connection: Connection = {
    mode: 'demo',
    async restore() {
      const token = await storage.get(TOKEN)
      return token ? open(token) : undefined
    },
    async signIn(email, password) {
      const { token } = engine.login(email, password)
      await storage.set(TOKEN, token)
      return (await open(token))!
    },
    async signOut() {
      const token = await storage.get(TOKEN)
      if (token) engine.logout(token)
      session = undefined
      await storage.remove(TOKEN)
    },
    client: guarded(() => session?.client),
    async admin<T>(name: string, ...args: unknown[]) {
      const fn = session?.admin[name]
      if (!fn) throw new EngineError(session ? 'invalid' : 'unauthenticated', session ? `unknown admin call ${name}` : 'sign in first')
      return (await fn(...args)) as T
    },
    async call(method, args) {
      const [area, name] = method.split('.')
      if (area === 'admin') return connection.admin(name, ...args)
      const fn = (connection.client as never as Record<string, Record<string, (...a: unknown[]) => Promise<unknown>>>)[area]?.[name]
      if (!fn) throw new EngineError('invalid', `unknown method ${method}`)
      return fn(...args)
    },
    // The demo has no file store: the image stays where the device saved it.
    uploadPhoto: async () => undefined,
    photoUrl: async (photo) => photo.uri,
    async reset() {
      const token = await storage.get(TOKEN)
      const who = token && engine.userForToken(token)
      store.data = fresh()
      engine = createEngine(store, demoPlatform)
      await storage.set(DEMO_DATA, JSON.stringify(store.data))
      session = undefined
      await storage.remove(TOKEN)
      if (who) {
        const { token: fresh } = engine.login(who.email, DEMO_PASSWORD)
        await storage.set(TOKEN, fresh)
        await open(fresh)
      }
    },
  }
  return connection
}
